{
  "summary": "This paper presents an anatomy-aware multimodal framework for predicting the T-stage of laryngopharyngeal cancer using 3D CT scans and paired radiology reports. The framework constructs an Anatomy-Structured Organ Graph (AOG) to model spatial relationships, aligns organ features with textual descriptions via Organ-Anchored Cross-Modal Alignment (OCA), and refines the graph using Report-Enhanced Graph-Refinement (REG). Evaluated on a multi-center cohort of 656 patients, the proposed method consistently outperforms state-of-the-art unimodal and multimodal baselines in both binary and three-class staging tasks.",
  "items": {
    "chk_problem": {
      "value": "Accurate T-staging of laryngopharyngeal cancer is critical for treatment planning, but CT-based staging is difficult due to complex tumor invasion patterns, and existing computer-aided methods lack structural relationship modeling and fine-grained cross-modal alignment.",
      "paper_quote": "Accurate T-staging is crucial for guiding personalized treatment strategies for laryngopharyngeal cancer."
    },
    "chk_method": {
      "value": "The proposed anatomy-aware multimodal framework integrates organ-level CT context and radiology reports using an Anatomy-Structured Organ Graph (AOG), Organ-Anchored Cross-Modal Alignment (OCA), and Report-Enhanced Graph-Refinement (REG).",
      "paper_quote": "To address these issues, we propose an anatomy-aware multimodal framework that integrates organ-level CT context and radiology reports into a unified representation for laryngopharyngeal T-staging."
    },
    "chk_data": {
      "value": "A multi-center dataset of 656 patients across four medical centers (FUZH, CGMH, EENT, and TCGA) with paired CT scans and radiology reports.",
      "paper_quote": "We conduct extensive experiments on a cohort of 656 patients from four hospitals (to our knowledge, the largest laryngopharyngeal T-staging dataset with paired CT and radiology reports), in both binary (T1–T2 vs. T3–T4) and three-class settings, and evaluate generalization on internal and external test sets, demonstrating consistent improvements over strong imaging-only and multimodal baselines."
    },
    "chk_setup": {
      "value": "Experiments were conducted using PyTorch on an NVIDIA H20 GPU, with CT volumes resampled to 1mm3, resized to 128x128x128, and normalized using a Hounsfield Unit window center of 50 and width of 450.",
      "paper_quote": "All experiments are conducted using PyTorch [41] on an NVIDIA H20 GPU."
    },
    "chk_primary_result": {
      "value": "In binary classification (early T1-T2 vs. late T3-T4), the proposed method achieved an F1 score of 80.83% and an accuracy of 81.53% on the internal test set.",
      "paper_quote": "For internal testing, we achieve an F1 score of 80.83% and accuracy of 81.53%, surpassing the second-best method MMI [3] (77.59% F1 score and 78.57% accuracy)."
    },
    "chk_secondary_result": {
      "value": "In the three-class classification task (T1 vs. T2 vs. T3-T4), the proposed method achieved an F1 score of 61.43% and an accuracy of 63.33% on the internal test set.",
      "paper_quote": "On the internal test set, we achieve an F1 score of 61.43% and accuracy of 63.33%, showing notable improvements over MMBCD [1] (58.44% F1 score and 61.14% accuracy)."
    },
    "chk_baseline": {
      "value": "The method was compared against image-only models (SwinViT, VDPF, MRSN) and state-of-the-art multimodal learning methods (CPAM, TGCAM, MMBCD, LViT, MMI).",
      "paper_quote": "We compare the proposed method with image-based classification approaches, such as SwinViT [37], VDPF [38], MRSN [39], and several state-of-the-art multimodal learning methods (CPAM [5], TGCAM [2], MMBCD [1], LViT [4], MMI [3])."
    },
    "chk_conclusion": {
      "value": "The proposed anatomy-structured multimodal framework consistently outperforms state-of-the-art unimodal and multimodal baselines in both binary and multi-class laryngopharyngeal cancer T-staging tasks, achieving performance on par with or exceeding experienced radiologists.",
      "paper_quote": "Extensive experiments on the largest curated laryngopharyngeal cancer T-staging dataset, as well as on public benchmarks, demonstrated that our proposed framework consistently outperforms state-of-the-art unimodal and multimodal baselines in both binary and multi-class staging tasks, achieving notable gains over radiologist assessments."
    },
    "chk_limitation": {
      "value": "The framework is limited by the inherent challenges of CT-based assessment, which can both over-estimate and under-estimate tumor invasion relative to pathological ground truth.",
      "paper_quote": "These complementary failure modes highlight an inherent challenge: CT-based assessment can both over-estimate and under-estimate invasion relative to pathological ground truth."
    }
  }
}
